const TEAM='The Dental Team, Dental Specialties, and History', AP='DENTAL Anatomy and Physiology', PATH='Dental Pathology', MORPH='Tooth Morphology', INF='Infection Control / Occupational Health and Safety', CHAIR='Chairside Assisting/Instruments (Including Restorative and Laboratory Materials)', RAD='Radiology', EMER='Medical Emergencies in the Dental Office';

export default {
 id:'dental-science-1',
 event:'Dental Science',
 title:'Practice Test 1',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Boyd’s Dental Instruments: A Pocket Guide and Robinson’s Modern Dental Assisting',
 plan:[{area:TEAM,weight:10},{area:AP,weight:10},{area:PATH,weight:10},{area:MORPH,weight:10},{area:INF,weight:10},{area:CHAIR,weight:30},{area:RAD,weight:10},{area:EMER,weight:10}],
 questions:mix([
  q(TEAM,'Which dental specialty treats diseases of the dental pulp, such as with root canal therapy?','Endodontics',['Periodontics','Prosthodontics','Orthodontics'],'B','Endodontists treat the pulp and periapical tissues. Periodontists treat gums and supporting bone, and prosthodontists replace missing teeth.',ROB),
  q(TEAM,'A patient needs treatment for severe bone loss around the teeth. Which specialist is most appropriate?','Periodontist',['Endodontist','Orthodontist','Pedodontist'],'D','Periodontics focuses on the gums, periodontal ligament and alveolar bone that support the teeth.',ROB),
  q(TEAM,'Which specialty focuses on restoring and replacing teeth with crowns, bridges, dentures and implants?','Prosthodontics',['Endodontics','Oral pathology','Public health dentistry'],'A','Prosthodontists restore function and appearance with fixed and removable prostheses.',ROB),
  q(TEAM,'Who is known as the “father of modern dentistry”?','Pierre Fauchard',['G.V. Black','Horace Wells','Hippocrates'],'C','Fauchard, a French surgeon, published a complete dental textbook in 1728. G.V. Black classified cavities, and Horace Wells pioneered anesthesia.',ROB),
  q(TEAM,'Which organization awards the Certified Dental Assistant (CDA) credential?','DANB',['ADA','ADHA','AAO'],'B','The Dental Assisting National Board offers the CDA exam. The ADA represents dentists and the ADHA represents dental hygienists.',ROB),
  q(AP,'Which is the only movable bone of the skull?','Mandible',['Maxilla','Zygomatic bone','Palatine bone'],'D','The mandible moves at the temporomandibular joint for chewing and speaking. The maxillae are fused to the skull.',ROB),
  q(AP,'The temporomandibular joint connects the mandible to which bone?','Temporal bone',['Maxilla','Occipital bone','Sphenoid bone'],'A','The condyle of the mandible fits into the glenoid fossa of the temporal bone, allowing hinge and gliding movements.',ROB),
  q(AP,'Which is the largest salivary gland?','Parotid gland',['Submandibular gland','Sublingual gland','Lacrimal gland'],'C','The parotid gland, in front of the ear, empties through Stensen’s duct opposite the maxillary second molar.',ROB),
  q(AP,'Which cranial nerve provides sensation to the teeth and is targeted by dental anesthesia?','Trigeminal nerve (CN V)',['Facial nerve (CN VII)','Vagus nerve (CN X)','Hypoglossal nerve (CN XII)'],'B','The maxillary and mandibular branches of the trigeminal nerve supply the teeth. The facial nerve controls facial expression.',ROB),
  q(AP,'Which is the strongest muscle of mastication?','Masseter',['Buccinator','Orbicularis oris','Lateral pterygoid'],'D','The masseter closes the jaw with great force. The buccinator and orbicularis oris are muscles of facial expression.',ROB),
  q(PATH,'Which bacterium is most closely linked to the start of dental caries?','Streptococcus mutans',['Escherichia coli','Staphylococcus aureus','Candida albicans'],'A','S. mutans metabolizes sugars into acid that demineralizes enamel. Candida is a fungus that causes thrush.',ROB),
  q(PATH,'What distinguishes periodontitis from gingivitis?','Loss of bone and attachment around the teeth',['Bleeding gums only','Inflammation limited to the gums','Damage that is always reversible'],'C','Gingivitis is reversible gum inflammation. Periodontitis destroys the periodontal ligament and bone and is not fully reversible.',ROB),
  q(PATH,'Creamy white patches in the mouth that wipe off and leave red areas suggest:','Oral candidiasis',['Leukoplakia','Lichen planus','Fluorosis'],'B','Candidiasis (thrush) is a fungal infection seen in infants, denture wearers and people with weakened immunity or using inhaled steroids. Leukoplakia does not wipe off.',ROB),
  q(PATH,'Why should leukoplakia be biopsied or closely monitored?','It can be a precancerous lesion',['It is always a viral infection','It is caused by brushing too hard','It always heals in a week'],'D','Leukoplakia is a white patch that cannot be scraped off. Some lesions contain dysplasia or cancer, especially in tobacco users.',ROB),
  q(PATH,'Chalky white spots or brown mottling of enamel caused by too much fluoride during tooth development is called:','Fluorosis',['Amelogenesis imperfecta','Attrition','Erosion'],'A','Excess fluoride while enamel is forming causes fluorosis. Attrition is wear from tooth-to-tooth contact, and erosion is chemical loss from acids.',ROB),
  q(MORPH,'How many teeth are in the primary and permanent dentitions?','20 primary and 32 permanent',['24 primary and 28 permanent','28 primary and 32 permanent','20 primary and 28 permanent'],'C','Children have 20 primary teeth. Adults have 32 permanent teeth, including four third molars.',ROB),
  q(MORPH,'In the Universal Numbering System, tooth #1 is the:','Maxillary right third molar',['Maxillary left third molar','Mandibular right central incisor','Mandibular left third molar'],'B','Numbering starts at the maxillary right third molar (#1), goes across to the maxillary left (#16), then down to the mandibular left third molar (#17) and around to #32.',ROB),
  q(MORPH,'Which is the hardest substance in the human body?','Enamel',['Dentin','Cementum','Bone'],'D','Enamel is about 96% mineral. Dentin forms the bulk of the tooth, and cementum covers the root.',ROB),
  q(MORPH,'On which tooth is the cusp of Carabelli usually found?','Maxillary first molar',['Mandibular first molar','Maxillary canine','Mandibular second premolar'],'A','The cusp of Carabelli is an extra cusp on the lingual surface of the mesiolingual cusp of the maxillary first molar.',ROB),
  q(MORPH,'Which tooth surface faces toward the midline of the dental arch?','Mesial',['Distal','Facial','Lingual'],'C','Mesial surfaces face the midline; distal surfaces face away. Facial faces the lips or cheeks, and lingual faces the tongue.',ROB),
  q(INF,'Under the Spaulding classification, how must critical instruments that penetrate soft tissue or bone be processed?','Heat sterilized',['Cleaned with soap only','Wiped with low-level disinfectant','Rinsed under running water'],'B','Critical items, such as forceps and scalers, must be sterilized. Semicritical items touch mucous membranes, and noncritical items touch intact skin.',ROB),
  q(INF,'How often should dental sterilizers be tested with biological (spore) indicators?','At least weekly',['Once a year','Only when they break','Every 5 years'],'D','Weekly spore testing, plus chemical indicators on every package, confirms the sterilizer is killing microorganisms.',ROB),
  q(INF,'If a dental assistant must recap a needle, which technique is safest?','One-handed scoop technique',['Two-handed recapping','Bending the needle first','Holding the cap between the teeth'],'A','The one-handed scoop or a recapping device keeps the free hand away from the needle, reducing needlestick risk.',ROB),
  q(INF,'How should barrier covers on light handles and switches be handled between patients?','Removed and replaced with new barriers',['Left in place for the whole day','Wiped with water and reused','Removed only at the end of the week'],'C','Barriers prevent contamination of hard-to-clean surfaces. They are changed after every patient, with surfaces disinfected if contaminated.',ROB),
  q(INF,'What standard does the CDC recommend for dental unit water used in nonsurgical treatment?','500 CFU/mL of bacteria or less',['Any tap water is acceptable','10,000 CFU/mL or less','Sterile saline for all procedures'],'B','Biofilm forms inside dental waterlines. Water used for routine care should meet drinking water standards of 500 CFU/mL or less.',ROB),
  q(CHAIR,'Which is NOT a common use of the mouth mirror?','Measuring periodontal pocket depth',['Indirect vision','Retracting the cheek or tongue','Reflecting light into the mouth'],'D','The mouth mirror provides indirect vision, retraction, illumination and transillumination. Pocket depths are measured with a periodontal probe.',BOYD),
  q(CHAIR,'What does a periodontal probe measure?','Pocket depth',['Tooth shade and color','Enamel hardness','Root canal length'],'A','The probe has millimeter markings to measure the depth of the gingival sulcus or periodontal pocket. Healthy depths are about 1–3 mm.',BOYD),
  q(CHAIR,'Which instrument is used to carry small items such as cotton pellets to and from the mouth?','Cotton pliers',['Excavator','Burnisher','Hemostat'],'C','Cotton pliers have pointed, serrated tips for grasping small items. The spoon excavator removes soft decay.',BOYD),
  q(CHAIR,'Which hand instrument removes soft carious dentin?','Spoon excavator',['Explorer','Condenser','Carver'],'B','The spoon excavator has a rounded, sharp blade for scooping out soft decay. An explorer detects decay, and a condenser packs amalgam.',BOYD),
  q(CHAIR,'After amalgam is placed in a preparation, which instrument packs it firmly?','Condenser (plugger)',['Amalgam carrier','Burnisher','Explorer'],'D','The carrier delivers the amalgam, the condenser packs it, the carver shapes it and the burnisher smooths it.',BOYD),
  q(CHAIR,'Which instrument smooths the surface and margins of a restoration?','Burnisher',['Spoon excavator','Periodontal probe','Cotton pliers'],'A','Burnishers have rounded, smooth ends that polish and adapt the restoration to the tooth.',BOYD),
  q(CHAIR,'For a Class II restoration, why are a matrix band and retainer placed?','To replace the missing proximal wall',['To isolate the tooth from saliva','To hold the rubber dam in place','To remove decay from the tooth'],'C','The matrix band (often in a Tofflemire retainer) replaces the missing wall so restorative material can be packed and contoured.',BOYD),
  q(CHAIR,'What is the low-speed handpiece most often used for?','Polishing and removing soft decay',['Cutting through enamel quickly','Suctioning fluids','Taking radiographs'],'B','The high-speed handpiece cuts enamel and dentin efficiently. The low-speed handpiece is used for polishing, finishing and caries removal.',BOYD),
  q(CHAIR,'In four-handed dentistry for a right-handed operator, where is the instrument transfer zone?','From about 4 to 7 o’clock',['From 8 to 11 o’clock','From 11 to 2 o’clock','Directly behind the patient at 12 o’clock'],'A','The transfer zone is over the patient’s chest, from about 4 to 7 o’clock. The operator works from about 8 to 11 o’clock.',ROB),
  q(CHAIR,'What is the main purpose of a dental dam?','To isolate the tooth and keep the area dry',['To numb the tooth','To hold the patient’s mouth open only','To whiten the teeth'],'C','The dam isolates teeth, improves visibility, keeps moisture out of restorations and protects the patient from swallowing debris.',ROB),
  q(CHAIR,'What is the main function of the high-volume evacuator (HVE)?','Removing fluid and debris',['Drying the tooth with air','Cooling the high-speed handpiece','Delivering anesthetic'],'B','The HVE removes water, saliva and debris quickly and reduces aerosols. The saliva ejector removes smaller amounts.',ROB),
  q(CHAIR,'How is most tooth-colored composite resin hardened?','With a curing light',['By mixing with water','By heating in an oven','By air drying for an hour'],'D','Light-cured composites harden when exposed to blue light of a specific wavelength. Protective shields or glasses protect the eyes.',ROB),
  q(CHAIR,'Alginate, used for study model impressions, is classified as:','Irreversible hydrocolloid',['Reversible hydrocolloid','Polyvinyl siloxane','Zinc oxide–eugenol'],'A','Once alginate sets, it cannot return to a sol state. Impressions must be poured promptly because alginate loses or absorbs water.',ROB),
  q(CHAIR,'Under G.V. Black’s classification, a cavity on the proximal surface of a premolar or molar is:','Class II',['Class I','Class III','Class V'],'C','Class I involves pits and fissures, Class II proximal surfaces of posterior teeth, Class III proximal surfaces of anterior teeth, and Class V the cervical third.',ROB),
  q(CHAIR,'Which instrument is used to detect calculus, decay and defects by feel?','Explorer',['Spoon excavator','Burnisher','Amalgam carrier'],'B','The explorer’s fine, sharp tip detects irregularities on tooth surfaces. It is part of the basic setup with the mirror and cotton pliers.',BOYD),
  q(RAD,'Which radiograph is best for detecting decay between posterior teeth?','Bitewing',['Periapical','Panoramic','Occlusal'],'D','Bitewings show the crowns of upper and lower posterior teeth and the bone crest on one film, ideal for interproximal caries.',ROB),
  q(RAD,'Which radiograph shows the entire tooth, including the root tip and surrounding bone?','Periapical',['Bitewing','Cephalometric','Occlusal'],'A','Periapical images capture the whole tooth and about 2 mm beyond the apex, used to evaluate abscesses and root problems.',ROB),
  q(RAD,'What does the ALARA principle require in dental radiography?','Keeping exposure as low as possible',['Taking as many images as possible','Using the longest exposure time','Avoiding lead aprons'],'C','ALARA uses fast receptors, proper technique, collimation, lead aprons with thyroid collars and only necessary images.',ROB),
  q(RAD,'How does dental decay appear on a radiograph?','Radiolucent (dark)',['Radiopaque (white)','Bright white with sharp edges','It cannot be seen'],'B','Decay is less dense, so more X-rays pass through and it appears dark. Metal restorations appear radiopaque (white).',ROB),
  q(RAD,'Which image shows both jaws, the teeth and the temporomandibular joints on one film?','Panoramic',['Bitewing','Periapical','Occlusal'],'D','A panoramic image gives a broad view for impacted teeth, jaw lesions and overall assessment, but less detail than intraoral images.',ROB),
  q(EMER,'What is the most common medical emergency in the dental office?','Syncope',['Heart attack','Stroke','Seizure'],'A','Fainting is often caused by anxiety. The patient is placed supine with the feet slightly elevated, and breathing and pulse are monitored.',ROB),
  q(EMER,'A patient with a history of angina develops chest pain during treatment. What should the team do first?','Stop and give nitroglycerin',['Continue the procedure quickly','Give the patient water','Lay the patient flat and wait'],'C','Stop the procedure, give oxygen and nitroglycerin as directed, and activate EMS if the pain is not relieved.',ROB),
  q(EMER,'A patient with diabetes who skipped breakfast becomes sweaty, shaky and confused. What should be given if the patient is conscious?','Fast-acting sugar',['Insulin','Nothing by mouth for now','Nitroglycerin'],'B','These are signs of hypoglycemia. A conscious patient can take fast-acting sugar. Scheduling diabetic patients after a meal helps prevent this.',ROB),
  q(EMER,'A patient develops hives, wheezing and swelling after exposure to latex gloves. What drug is used for this anaphylactic reaction?','Epinephrine',['Nitroglycerin','Aspirin','Glucose'],'D','Epinephrine reverses airway swelling and low blood pressure. EMS is called, and oxygen is given.',ROB),
  q(EMER,'A patient with asthma begins wheezing during treatment. What should the team do?','Stop and give their rescue inhaler',['Recline the patient fully flat','Give the patient a sedative','Keep working faster'],'A','Seat the patient upright, have them use their rescue inhaler and give oxygen. Patients with asthma should bring their inhaler to appointments.',ROB)
 ],109)
};
